class Solution {
public:
    int maxDiff(int num) {
        int digits[10];
        int n = 0;
        int temp = num;
        while (temp > 0) {
            digits[n++] = temp % 10;
            temp /= 10;
        }
        // digits[0] = least significant, digits[n-1] = most significant

        // Max: replace first non-9 digit (from MSB) with 9
        int maxVal = num;
        int targetMax = -1;
        for (int i = n - 1; i >= 0; i--) {
            if (digits[i] != 9) {
                targetMax = digits[i];
                break;
            }
        }
        if (targetMax != -1) {
            maxVal = 0;
            for (int i = n - 1; i >= 0; i--) {
                int d = (digits[i] == targetMax) ? 9 : digits[i];
                maxVal = maxVal * 10 + d;
            }
        }

        // Min:
        // If leading digit != 1, replace all its occurrences with 1
        // If leading digit == 1, find first digit > 1 and replace with 0
        int minVal = num;
        int targetMin = -1;
        int replaceWith = 0;
        if (digits[n - 1] != 1) {
            targetMin = digits[n - 1];
            replaceWith = 1;
        } else {
            for (int i = n - 2; i >= 0; i--) {
                if (digits[i] > 1) {
                    targetMin = digits[i];
                    replaceWith = 0;
                    break;
                }
            }
        }
        if (targetMin != -1) {
            minVal = 0;
            for (int i = n - 1; i >= 0; i--) {
                int d = (digits[i] == targetMin) ? replaceWith : digits[i];
                minVal = minVal * 10 + d;
            }
        }

        return maxVal - minVal;
    }
};
